import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_matmul_cuda = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cstdint>
#define BM 128
#define BN 128
#define BK 16
#define ABK (BK + 4)
#define BBNS (BN + 4)
#define TM 8
#define TN 8
#define STAGES 3
#define MAX_SPLITS 256
__device__ __forceinline__ void cp_async16(void* smem, const void* gmem, int src_bytes) {
    unsigned saddr = static_cast<unsigned>(__cvta_generic_to_shared(smem));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16, %2;\n"
                 :: "r"(saddr), "l"(gmem), "r"(src_bytes));
}
__device__ __forceinline__ void cp_async_commit() {
    asm volatile("cp.async.commit_group;\n" ::);
}
__device__ __forceinline__ void cp_async_wait1() {
    asm volatile("cp.async.wait_group 1;\n" ::);
}
__device__ __forceinline__ void cp_async_wait0() {
    asm volatile("cp.async.wait_group 0;\n" ::);
}
__global__ void __launch_bounds__(256) matmul_partial_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ P,
    const int M,
    const int N,
    const int K,
    const int k_tiles_total,
    const int tiles_per_split) {
    extern __shared__ float smem[];
    float* As = smem;
    float* Bs = smem + STAGES * BM * ABK;
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * 16 + tx;
    const int m0 = blockIdx.y * BM;
    const int n0 = blockIdx.x * BN;
    const int split = blockIdx.z;
    const int k_tile_begin = split * tiles_per_split;
    int k_tile_end = k_tile_begin + tiles_per_split;
    if (k_tile_end > k_tiles_total) {
        k_tile_end = k_tiles_total;
    }
    const int a_chunks = (BM * BK) / 4;
    const int b_chunks = (BK * BN) / 4;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    auto load_tile = [&](int buf, int kt) {
        const int k0 = kt * BK;
        #pragma unroll
        for (int c = tid; c < a_chunks; c += 256) {
            const int row = c >> 2;
            const int col = (c & 3) * 4;
            const int m_load = m0 + row;
            const int k = k0 + col;
            const float* src = A + static_cast<long long>(m_load) * K + k;
            float* dst = &As[(buf * BM + row) * ABK + col];
            int bytes = 0;
            if (m_load < M) {
                bytes = (K - k) * 4;
                if (bytes < 0) bytes = 0;
                if (bytes > 16) bytes = 16;
            }
            if (bytes > 0 && ((reinterpret_cast<uintptr_t>(src) & 15) == 0)) {
                cp_async16(dst, src, bytes);
            } else if (bytes == 0) {
                dst[0] = 0.0f;
                dst[1] = 0.0f;
                dst[2] = 0.0f;
                dst[3] = 0.0f;
            } else {
                float v0 = 0.0f, v1 = 0.0f, v2 = 0.0f, v3 = 0.0f;
                if (k < K) v0 = A[static_cast<long long>(m_load) * K + k];
                if (k + 1 < K) v1 = A[static_cast<long long>(m_load) * K + k + 1];
                if (k + 2 < K) v2 = A[static_cast<long long>(m_load) * K + k + 2];
                if (k + 3 < K) v3 = A[static_cast<long long>(m_load) * K + k + 3];
                dst[0] = v0;
                dst[1] = v1;
                dst[2] = v2;
                dst[3] = v3;
            }
        }
        #pragma unroll
        for (int c = tid; c < b_chunks; c += 256) {
            const int row = c >> 5;
            const int col = (c & 31) * 4;
            const int k = k0 + row;
            const int n_load = n0 + col;
            const float* src = B + static_cast<long long>(k) * N + n_load;
            float* dst = &Bs[(buf * BK + row) * BBNS + col];
            int bytes = 0;
            if (k < K) {
                bytes = (N - n_load) * 4;
                if (bytes < 0) bytes = 0;
                if (bytes > 16) bytes = 16;
            }
            if (bytes > 0 && ((reinterpret_cast<uintptr_t>(src) & 15) == 0)) {
                cp_async16(dst, src, bytes);
            } else if (bytes == 0) {
                dst[0] = 0.0f;
                dst[1] = 0.0f;
                dst[2] = 0.0f;
                dst[3] = 0.0f;
            } else {
                float v0 = 0.0f, v1 = 0.0f, v2 = 0.0f, v3 = 0.0f;
                if (n_load < N) v0 = B[static_cast<long long>(k) * N + n_load];
                if (n_load + 1 < N) v1 = B[static_cast<long long>(k) * N + n_load + 1];
                if (n_load + 2 < N) v2 = B[static_cast<long long>(k) * N + n_load + 2];
                if (n_load + 3 < N) v3 = B[static_cast<long long>(k) * N + n_load + 3];
                dst[0] = v0;
                dst[1] = v1;
                dst[2] = v2;
                dst[3] = v3;
            }
        }
    };
    if (k_tile_begin < k_tile_end) {
        load_tile(0, k_tile_begin);
        cp_async_commit();
        if (k_tile_begin + 1 < k_tile_end) {
            load_tile(1, k_tile_begin + 1);
            cp_async_commit();
        }
    }
    for (int kt = k_tile_begin; kt < k_tile_end; ++kt) {
        const int cur = (kt - k_tile_begin) % STAGES;
        const int pf = kt + STAGES - 1;
        if (pf < k_tile_end) {
            load_tile((pf - k_tile_begin) % STAGES, pf);
            cp_async_commit();
        }
        if (kt + 1 < k_tile_end) {
            cp_async_wait1();
        } else {
            cp_async_wait0();
        }
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float av[TM];
            float bv[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                av[i] = As[(cur * BM + ty * TM + i) * ABK + kk];
            }
            const float4 b0 = *reinterpret_cast<const float4*>(&Bs[(cur * BK + kk) * BBNS + tx * TN]);
            const float4 b1 = *reinterpret_cast<const float4*>(&Bs[(cur * BK + kk) * BBNS + tx * TN + 4]);
            bv[0] = b0.x; bv[1] = b0.y; bv[2] = b0.z; bv[3] = b0.w;
            bv[4] = b1.x; bv[5] = b1.y; bv[6] = b1.z; bv[7] = b1.w;
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    acc[i][j] += av[i] * bv[j];
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int row = m0 + ty * TM + i;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int col = n0 + tx * TN + j;
            if (row < M && col < N) {
                P[(static_cast<long long>(split) * M + row) * N + col] = acc[i][j];
            }
        }
    }
}
__global__ void splitk_reduce_kernel(
    const float* __restrict__ P,
    float* __restrict__ C,
    const int total,
    const int splits) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total) {
        float sum = 0.0f;
        for (int s = 0; s < splits; ++s) {
            sum += P[static_cast<long long>(s) * total + idx];
        }
        C[idx] = sum;
    }
}
torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.scalar_type() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");
    auto Ac = A.contiguous();
    auto Bc = B.contiguous();
    const int M = static_cast<int>(Ac.size(0));
    const int K = static_cast<int>(Ac.size(1));
    const int N = static_cast<int>(Bc.size(1));
    auto C = torch::empty({M, N}, Ac.options());
    const int total = M * N;
    if (total == 0) {
        return C;
    }
    const int k_tiles_total = (K + BK - 1) / BK;
    int splits = k_tiles_total < MAX_SPLITS ? k_tiles_total : MAX_SPLITS;
    if (splits < 1) {
        splits = 1;
    }
    const int tiles_per_split = (k_tiles_total + splits - 1) / splits;
    auto partial = torch::empty({splits, M, N}, Ac.options());
    dim3 block(16, 16);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM, splits);
    const size_t shmem_bytes = static_cast<size_t>(STAGES) * (BM * ABK + BK * BBNS) * sizeof(float);
    static bool smem_configured = false;
    if (!smem_configured) {
        cudaFuncSetAttribute(matmul_partial_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, static_cast<int>(shmem_bytes));
        smem_configured = true;
    }
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    matmul_partial_kernel<<<grid, block, shmem_bytes, stream>>>(
        Ac.data_ptr<float>(),
        Bc.data_ptr<float>(),
        partial.data_ptr<float>(),
        M, N, K, k_tiles_total, tiles_per_split);
    dim3 reduce_block(256);
    dim3 reduce_grid((total + 255) / 256);
    splitk_reduce_kernel<<<reduce_grid, reduce_block, 0, stream>>>(
        partial.data_ptr<float>(),
        C.data_ptr<float>(),
        total, splits);
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed: ", cudaGetErrorString(err));
    return C;
}
"""

_matmul_cpp = r"""
torch::Tensor matmul(torch::Tensor A, torch::Tensor B);
"""

_ext = load_inline(
    name="modelnew_matmul_ext",
    cpp_sources=[_matmul_cpp],
    cuda_sources=[_matmul_cuda],
    functions=["matmul"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        return _ext.matmul(A, B)

